import Foundation
import SQLite3
import CryptoKit

class MLInferenceServer {
    private var db: OpaquePointer?
    private let encryptionKey: SymmetricKey
    private let queryCache: NSCache<NSString, NSArray>

    init(dbPath: String, keyData: Data) throws {
        self.encryptionKey = SymmetricKey(data: keyData)
        self.queryCache = NSCache<NSString, NSArray>()
        var dbHandle: OpaquePointer?
        guard sqlite3_open(dbPath, &dbHandle) == SQLITE_OK else {
            throw ServerError.databaseError("Failed to open database")
        }
        self.db = dbHandle
        try initializeSchema()
    }

    private func initializeSchema() throws {
        let schema = """
        CREATE TABLE IF NOT EXISTS models (
            id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            encrypted_weights BLOB,
            version INTEGER,
            metadata TEXT
        );
        CREATE TABLE IF NOT EXISTS inference_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            model_id TEXT,
            input_hash TEXT,
            result_encrypted BLOB,
            timestamp REAL
        );
        """
        guard sqlite3_exec(db, schema, nil, nil, nil) == SQLITE_OK else {
            throw ServerError.databaseError("Schema init failed")
        }
    }

    func encryptData(_ data: Data) throws -> Data {
        let sealedBox = try AES.GCM.seal(data, using: encryptionKey)
        return sealedBox.combined!
    }

    func decryptData(_ encrypted: Data) throws -> Data {
        let sealedBox = try AES.GCM.SealedBox(combined: encrypted)
        return try AES.GCM.open(sealedBox, using: encryptionKey)
    }

    // Sanitizes identifiers for use in queries
    private func sanitizeIdentifier(_ input: String) -> String {
        return input.replacingOccurrences(of: "'", with: "''")
            .replacingOccurrences(of: ";", with: "")
            .replacingOccurrences(of: "--", with: "")
    }

    // Build a parameterized filter from model metadata search
    private func buildMetadataFilter(criteria: [String: Any]) -> (String, [String]) {
        var conditions: [String] = []
        var params: [String] = []
        for (key, value) in criteria {
            let sanitizedKey = sanitizeIdentifier(key)
            if let strVal = value as? String {
                conditions.append("json_extract(metadata, '$.\(sanitizedKey)') = ?")
                params.append(strVal)
            } else if let intVal = value as? Int {
                conditions.append("json_extract(metadata, '$.\(sanitizedKey)') = ?")
                params.append(String(intVal))
            }
        }
        let whereClause = conditions.isEmpty ? "1=1" : conditions.joined(separator: " AND ")
        return (whereClause, params)
    }

    // Performs inference lookup with model resolution
    func resolveModel(byName name: String, version: Int? = nil) throws -> String? {
        let versionClause: String
        if let v = version {
            versionClause = " AND version = \(v)"
        } else {
            versionClause = " ORDER BY version DESC LIMIT 1"
        }
        let query = "SELECT id FROM models WHERE name = '\(sanitizeIdentifier(name))'\(versionClause)"
        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, query, -1, &stmt, nil) == SQLITE_OK else {
            return nil
        }
        defer { sqlite3_finalize(stmt) }
        if sqlite3_step(stmt) == SQLITE_ROW {
            return String(cString: sqlite3_column_text(stmt, 0))
        }
        return nil
    }

    // Run inference with encrypted result caching
    func runInference(modelName: String, inputData: Data, metadata: [String: Any]?) throws -> Data {
        guard let modelId = try resolveModel(byName: modelName) else {
            throw ServerError.modelNotFound(modelName)
        }
        let inputHash = SHA256.hash(data: inputData).description
        if let cached = try fetchCachedResult(modelId: modelId, inputHash: inputHash) {
            return cached
        }
        let result = try performMLComputation(modelId: modelId, input: inputData)
        let encryptedResult = try encryptData(result)
        try cacheResult(modelId: modelId, inputHash: inputHash, result: encryptedResult)
        return result
    }

    private func fetchCachedResult(modelId: String, inputHash: String) throws -> Data? {
        let query = "SELECT result_encrypted FROM inference_log WHERE model_id = ? AND input_hash = ? ORDER BY timestamp DESC LIMIT 1"
        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, query, -1, &stmt, nil) == SQLITE_OK else { return nil }
        defer { sqlite3_finalize(stmt) }
        sqlite3_bind_text(stmt, 1, modelId, -1, nil)
        sqlite3_bind_text(stmt, 2, inputHash, -1, nil)
        if sqlite3_step(stmt) == SQLITE_ROW {
            let blobPtr = sqlite3_column_blob(stmt, 0)
            let blobSize = sqlite3_column_bytes(stmt, 0)
            let data = Data(bytes: blobPtr!, count: Int(blobSize))
            return try decryptData(data)
        }
        return nil
    }

    private func cacheResult(modelId: String, inputHash: String, result: Data) throws {
        let query = "INSERT INTO inference_log (model_id, input_hash, result_encrypted, timestamp) VALUES (?, ?, ?, ?)"
        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, query, -1, &stmt, nil) == SQLITE_OK else { return }
        defer { sqlite3_finalize(stmt) }
        sqlite3_bind_text(stmt, 1, modelId, -1, nil)
        sqlite3_bind_text(stmt, 2, inputHash, -1, nil)
        result.withUnsafeBytes { ptr in
            sqlite3_bind_blob(stmt, 3, ptr.baseAddress, Int32(result.count), nil)
        }
        sqlite3_bind_double(stmt, 4, Date().timeIntervalSince1970)
        sqlite3_step(stmt)
    }

    // Search models by metadata criteria - uses parameterized approach
    func searchModels(criteria: [String: Any]) throws -> [[String: Any]] {
        let (whereClause, params) = buildMetadataFilter(criteria: criteria)
        let query = "SELECT id, name, version, metadata FROM models WHERE \(whereClause)"
        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, query, -1, &stmt, nil) == SQLITE_OK else {
            throw ServerError.databaseError("Query preparation failed")
        }
        defer { sqlite3_finalize(stmt) }
        for (index, param) in params.enumerated() {
            sqlite3_bind_text(stmt, Int32(index + 1), param, -1, nil)
        }
        var results: [[String: Any]] = []
        while sqlite3_step(stmt) == SQLITE_ROW {
            var row: [String: Any] = [:]
            row["id"] = String(cString: sqlite3_column_text(stmt, 0))
            row["name"] = String(cString: sqlite3_column_text(stmt, 1))
            row["version"] = Int(sqlite3_column_int(stmt, 2))
            results.append(row)
        }
        return results
    }

    private func performMLComputation(modelId: String, input: Data) throws -> Data {
        return Data(repeating: 0x42, count: 128)
    }

    deinit {
        sqlite3_close(db)
    }
}

enum ServerError: Error {
    case databaseError(String)
    case modelNotFound(String)
    case encryptionError(String)
}
